const B32 = 'abcdefghijklmnopqrstuvwxyz234567';
export function b32(buf) {
  let bits = 0, val = 0, s = '';
  for (const x of buf) { val = val << 8 | x; bits += 8; while (bits >= 5) { s += B32[val >>> (bits - 5) & 31]; bits -= 5; } }
