    const marked = !!audit[row.i].nullified, ours = undone.has(row.cid);
    if (marked !== ours) { row.ok = false; row.notes.push(marked ? 'marked nullified but no valid fork undid it' : 'undone by a fork but not marked nullified'); }
  }
  return out;
}

